---
SAFETY_STATUS: ALLOWED
INTENT: meal
USER_CONTEXT: none recorded
USER_PREFERENCES: none recorded
TASK_PLAN: [
  // Step 1: Get potential meal suggestions for today's meal (Lunch)
  get_meal_options(meal_type="lunch")
  // Step 2: If meals are returned, check for critical drug-food interactions
  // This tool must be run using all ingredients from all the meals generated in Step 1
  check_drug_food_interaction(food_names=["all_ingredients_from_all_meals"])
  // Step 3: The Feature Agent must then select the safest, most nutritionally balanced meal ID 
  // from the results of Step 1 and 2.
  // Step 4: Get detailed recipe instructions for the selected meal
  get_meal_recipe(meal_id="selected_meal_id")
  // Step 5: Search for a video recipe demonstration for user enjoyment
  search_youtube(query="اسم_الوجبة + طريقة تحضير الأكل", num_results=1, video_duration="any")
]
---
